import React from 'react';import {createRoot} from 'react-dom/client';import {MemoryRouter,useNavigate} from 'react-router-dom';
import {InspectionWorkspaceBody} from '../../src/modules/electrical-inspections/ElectricalInspectionWorkspace.jsx';
import {JobPermitRegisterBody} from '../../src/modules/electrical-inspections/JobPermitRegister.jsx';
import {blankInspection,blankEquipment} from '../../src/modules/electrical-inspections/inspectionModel.js';
import {DEFAULT_SERVICE_STAGES} from '../../src/modules/service-calls/serviceStages.js';
import '../../src/styles/tokens.css';import '../../src/styles/base.css';import '../../src/styles/primitives.css';
const requests=[],records=[],files=new Map();let failSave=false;
const job={id:'00000000-0000-4000-8000-000000000001',name:'Example Service Call',number:'TEST-001',division:'Electrical',job_type:'service_call'};
const register={can_edit:true,permits:[],inspections:[],health:[],documents:[]};
const readonly=new URLSearchParams(location.search).has('readonly');
const api={async rpc(name,args={}){requests.push({name,args:structuredClone(args)});if(name==='hi_read'){if(!args.p_id)return records.map(r=>({...r,client_name:r.document.client.clientName,site_address:r.document.client.siteAddress,visit_date:r.document.visitDate,technician:'Test technician'}));const row=records.find(r=>r.id===args.p_id);if(!row)throw Error('Inspection unavailable');return structuredClone({...row,can_edit:!readonly&&['draft','in_progress'].includes(row.workflow),can_review:!readonly,can_assign:!readonly});}
 if(name==='hi_people')return [{id:'tester',name:'Test technician'},{id:'reviewer',name:'Test reviewer'}];
 if(name==='hi_save'){if(failSave){failSave=false;throw Error('Simulated connection lost. Retry this save.');}let row=records.find(r=>r.id===args.p_id);if(!row){row={id:crypto.randomUUID(),inspection_number:'HI-TEST-001',version:0,workflow:'draft',division:'Electrical',assigned_to:'tester',files:[],revisions:[],history:[],job:null};records.push(row);}if(args.p_id&&row.version!==args.p_expected_version)throw Error('Inspection changed. Reload before saving.');row.document=structuredClone(args.p_document);row.version++;row.workflow='in_progress';return {id:row.id,version:row.version};}
 if(name==='hi_action'){const row=records.find(r=>r.id===args.p_id);if(row.version!==args.p_expected_version)throw Error('Inspection changed. Reload before this action.');if(args.p_action==='submit')row.workflow='ready_for_review';if(args.p_action==='return'||args.p_action==='revise')row.workflow='in_progress';if(args.p_action==='issue'){row.document={...row.document,...args.p_data};row.workflow='issued';const revision={id:crypto.randomUUID(),revision:row.revisions.length+1,inspection_id:row.id,document:structuredClone(row.document),issued_at:'2026-09-14T23:00:00.000Z',reviewer_name:'Test reviewer',job_snapshot:row.job,file_ids:row.files.filter(f=>f.kind==='photo').map(f=>f.id)};row.revisions.unshift(revision);}if(args.p_action==='assign')row.assigned_to=args.p_data.assigned_to;if(['link','create_call'].includes(args.p_action))row.job=job;row.version++;row.history.unshift({user_name:'Test user',created_at:new Date().toISOString(),note:args.p_action+': '+args.p_reason});return {id:row.id,version:row.version,revision_id:args.p_action==='issue'?row.revisions[0].id:null};}
 if(name==='hi_jobs')return [job];if(name==='svc_read_stages')return DEFAULT_SERVICE_STAGES;if(name==='svc_read_calls')return [];
 if(name==='hi_job_register')return structuredClone(register);if(name==='hi_job_register_save'){const rows=args.p_kind==='permit'?register.permits:register.inspections;const row={...args.p_data,id:args.p_id||crypto.randomUUID(),version:1};rows.push(row);return row;}if(name==='hi_original')return null;throw Error('Unhandled fixture RPC '+name);},
 async upload(item){requests.push({name:'upload',kind:item.kind,revisionId:item.revisionId});const row=records.find(r=>r.id===item.inspection),bytes=await item.file.arrayBuffer();const sha=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');files.set(item.id,new Blob([bytes],{type:item.file.type}));const saved={id:item.id,kind:item.kind,status:'ready',file_name:item.file.name,storage_path:item.id,sha256:sha,mime_type:item.file.type,caption:item.caption||'',equipment_id:item.equipmentId||'',finding_id:item.findingId||''};row.files.push(saved);return saved;},async download(path){return files.get(path);}};
window.inspectionFixture={requests,records,register,failSave(){failSave=true;},stale(){records[0].version++;}};
if(readonly){const d=blankInspection();d.client.clientName='Example Facility';d.equipment=[blankEquipment()];records.push({id:crypto.randomUUID(),inspection_number:'HI-TEST-001',document:d,version:1,workflow:'issued',division:'Electrical',assigned_to:'tester',files:[],revisions:[],history:[]});}
function NavigationProbe(){const navigate=useNavigate();window.inspectionFixture.navigate=navigate;return null;}
createRoot(document.getElementById('root')).render(<MemoryRouter><NavigationProbe/><main style={{padding:16}}>{new URLSearchParams(location.search).has('permits')?<JobPermitRegisterBody job={job} permissions={{canArchiveRecords:true}} api={api}/>:<InspectionWorkspaceBody api={api} permissions={{canCreateJobs:!readonly,canArchiveRecords:!readonly,department:'Electrical'}}/>}</main></MemoryRouter>);
